import{_ as e,o,c as s,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const a="/rakkii-cars-guide/screenshots/v2/a06-work-lines.png",n="/rakkii-cars-guide/screenshots/v2/a07-quote-card.png",i="/rakkii-cars-guide/screenshots/v2/a07b-quote-more.png",k=JSON.parse('{"title":"2. Add work and save the quote","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/02-work-and-quote.md","filePath":"desk/job/02-work-and-quote.md","lastUpdated":1794621279000}'),d={name:"desk/job/02-work-and-quote.md"};function h(l,t,u,g,p,c){return o(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="_2-add-work-and-save-the-quote" tabindex="-1">2. Add work and save the quote <a class="header-anchor" href="#_2-add-work-and-save-the-quote" aria-label="Permalink to &quot;2. Add work and save the quote&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> the job&#39;s <strong>Work</strong> tab · <strong>Status after:</strong> Quoted</p><p>The quote lives on the <strong>Work</strong> tab, right under the work lines. There is no separate Quote tab.</p><h2 id="add-the-work-lines" tabindex="-1">Add the work lines <a class="header-anchor" href="#add-the-work-lines" aria-label="Permalink to &quot;Add the work lines&quot;">​</a></h2><ol><li>Open the <strong>Work</strong> tab and press <strong>Add line</strong> on the <strong>Work lines</strong> card.</li><li>Choose the <strong>Kind</strong>: Labor, Part, Paint, Fee or Other. <ul><li>For a part, pick a <strong>Catalog part</strong> (it shows what&#39;s in stock), or leave it empty and just type the description.</li></ul></li><li>Enter the <strong>Description</strong>, <strong>Qty</strong>, <strong>Cost</strong> (what it costs the shop) and <strong>Sell</strong> (the customer&#39;s price).</li><li><strong>Who pays</strong>: Customer. (On insurance jobs, choose <strong>Insurer</strong> for lines the insurer covers.)</li><li>Press <strong>Save line</strong>. Repeat for each line.</li></ol><p><img src="'+a+'" alt="Work lines and the Quote card"></p><div class="tip custom-block"><p class="custom-block-title">Need supplier prices first?</p><p>Use <strong>More ▾ › Add canvass step</strong> in the job header. A <strong>Canvass</strong> tab appears for collecting supplier quotes. See <a href="/rakkii-cars-guide/reference/09-parts-inventory-canvass-restock-payables">Parts, canvass &amp; payables</a>.</p></div><h2 id="save-the-quote" tabindex="-1">Save the quote <a class="header-anchor" href="#save-the-quote" aria-label="Permalink to &quot;Save the quote&quot;">​</a></h2><ol><li>On the <strong>Quote</strong> card, check the total and the margin chip in the header (for example <strong>Margin 92% on cost</strong>).</li><li>Press <strong>Save quote</strong>. The app asks &quot;Save the quote?&quot; and reminds you that nothing is sent to the customer yet. Press <strong>Save quote</strong> again.</li><li>The status becomes <strong>Quoted</strong>, and the card shows the quote, for example &quot;Last quote: ₱2,300.00 · Pending · Not emailed&quot;.</li></ol><p><img src="'+n+'" alt="Quote card after saving"></p><p><strong>Quote card › More ▾</strong> has:</p><ul><li><strong>Preview estimate</strong> and <strong>Print estimate</strong></li><li><strong>Copy customer link</strong>: the link the customer uses to see and approve the estimate</li></ul><p><img src="'+i+'" alt="Quote card More menu"></p><p>Press <strong>Email quote</strong> to email the estimate to the customer.</p><div class="tip custom-block"><p class="custom-block-title">Quote given by phone or on paper?</p><p>Before you save a quote in the app, the job&#39;s status buttons include <strong>Mark quoted (sent outside the app)</strong>. Use it when the customer already has a price from you.</p></div><h2 id="if-something-stops-you" tabindex="-1">If something stops you <a class="header-anchor" href="#if-something-stops-you" aria-label="Permalink to &quot;If something stops you&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You see</th><th>What to do</th></tr></thead><tbody><tr><td>&quot;Save quote is off: add a work line first.&quot;</td><td>Add at least one work line.</td></tr><tr><td>The margin is under the shop&#39;s minimum (30% by default)</td><td>In warn mode you can still save. In block mode the owner types a <strong>Margin override reason</strong>.</td></tr><tr><td>A warning that the work lines changed since the last quote</td><td>Press <strong>Save quote</strong> again so the customer sees the new total.</td></tr></tbody></table><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/03-customer-approval">3. Get the customer&#39;s OK</a></p>',18)])])}const q=e(d,[["render",h]]);export{k as __pageData,q as default};
